    <script>
    const streamlitDoc = window.parent.document;

    // Function to hide elements containing specific text or attributes like "streamlit.io"
    function removeBranding() {
        // Target links pointing to streamlit.io (covers Hosted with Streamlit badges)
        streamlitDoc.querySelectorAll('[href*="streamlit.io"]').forEach(el => {
